@[ext]
theorem ext {v w : Place k K}
    (h : v.toValuationSubring = w.toValuationSubring) : v = w

lemma eq_single_of_effective_deg_one {D : DivisorA k K}
    (hD : IsEffective k K D) (hdeg : deg k K D = 1) :
    ∃ v : PlaceA k K, placeDegree k K v = 1 ∧ D = Finsupp.single v 1

theorem smulWeil_toFun_mem_differentialSpace (ω : WeilDifferential k K) {D₀ : DivisorA k K}
    (h : D₀ ∈ vanishingDivisors ω) {E : DivisorA k K} (f : RRspace k K E) :
    (smulWeil (f : K) ω).toFun ∈ differentialSpace (k := k) (K := K) (D₀ - E)

theorem smulIntoOmega_injective (ω : WeilDifferential k K) {D₀ : DivisorA k K}
    (h : D₀ ∈ vanishingDivisors ω) (E : DivisorA k K) (hω : ω.toFun ≠ 0) :
    Function.Injective (smulIntoOmega ω h E)

theorem sup_mem_vanishingDivisors {ω : WeilDifferential k K} {D₁ D₂ : DivisorA k K}
    (hD₁ : D₁ ∈ vanishingDivisors ω) (hD₂ : D₂ ∈ vanishingDivisors ω) :
    D₁ ⊔ D₂ ∈ vanishingDivisors ω

theorem isCanonical_unique_up_to_principal {W₁ W₂ : DivisorA k K}
    (h₁ : IsCanonical k K W₁) (h₂ : IsCanonical k K W₂) :
    ∃ f : Kˣ, W₁ - W₂ = principalDivisorA k K (Additive.ofMul f)

theorem adeleSubmodule_top_eq_adeleFilt_add_diagonal {D : DivisorA k K}
    (hD : defect k K D = genus k K) :
    topAdeleSubmodule k K = adeleFilt k K D + diagonalSubmodule k K

theorem maximalIdeal_infty_eq_span_t :
    IsLocalRing.maximalIdeal (inftyValuationSubring k) =
      Ideal.span {(tA k : inftyValuationSubring k)}

theorem map_maximalIdeal_infty :
    Ideal.map (algebraMap inftyRing inftyInts) maxIdealInfty =
      Ideal.span {algebraMap inftyRing inftyInts (tA k)}
